contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Try Put with an arbitrary lock time and amount (sent as msg.value)
    function run(uint lockTime, uint sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sendAmount)); require(sendAmount <= 1000000000000000000000000000000);
        // ensure this contract has enough Ether to send
        require(address(this).balance >= sendAmount);

        // read before values for this test contract's holder and contract balance
        (uint beforeUnlock, uint beforeHolderBalance) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBalance = address(c).balance;

        // call Put sending sendAmount wei and capture whether it reverted
        bool reverted;
        // top-level state-changing call
        c.Put{value: sendAmount}(lockTime); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after values
        (uint afterUnlock, uint afterHolderBalance) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBalance = address(c).balance;

        // General rule:
        // - If the call reverted, nothing observable about c should have changed.
        // - If it succeeded, the holder's recorded balance did not decrease, and the contract balance increased by at most the sent amount,
        //   and the increase in holder.balance is no more than the increase in contract balance (i.e., no phantom credit beyond Ether received).
        assert(
            reverted
            ? (afterHolderBalance == beforeHolderBalance && afterContractBalance == beforeContractBalance)
            : (
                // holder balance did not decrease
                afterHolderBalance >= beforeHolderBalance
                // contract balance increased by at most sendAmount
                && afterContractBalance >= beforeContractBalance
                && (afterContractBalance - beforeContractBalance) <= sendAmount
                // holder's increase cannot exceed contract's increase
                && (afterHolderBalance - beforeHolderBalance) <= (afterContractBalance - beforeContractBalance)
            )
        );
    }

    receive() external payable {}
}

