// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 lockTime, uint256 sendAmount) internal {
        sendAmount = bound(sendAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmount);
        uint256 beforeUnlock;
        uint256 beforeHolderBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { beforeUnlock = __r0; beforeHolderBalance = __r1; } catch { return; }
        uint beforeContractBalance = address(c).balance;
        bool reverted;
        try c.Put{value: sendAmount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterUnlock;
        uint256 afterHolderBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { afterUnlock = __r0; afterHolderBalance = __r1; } catch { return; }
        uint afterContractBalance = address(c).balance;
        assertTrue(reverted
            ? (afterHolderBalance == beforeHolderBalance && afterContractBalance == beforeContractBalance)
            : (
                // holder balance did not decrease
                afterHolderBalance >= beforeHolderBalance
                // contract balance increased by at most sendAmount
                && afterContractBalance >= beforeContractBalance
                && (afterContractBalance - beforeContractBalance) <= sendAmount
                // holder's increase cannot exceed contract's increase
                && (afterHolderBalance - beforeHolderBalance) <= (afterContractBalance - beforeContractBalance)
            ));
    }

    function testFuzz_run(uint256 lockTime, uint256 sendAmount) public {
        _run(lockTime, sendAmount);
    }

    receive() external payable {}
}
